// TOC scroll-spy(移植自 DCLogic componentDidMount)
let spy: (() => void) | null = null

onMounted(() => {
  spy = function () {
    const ids = ['s1', 's2', 's3', 's4', 's5']
    let current = ids[0]
    ids.forEach(function (id) {
      const el = document.getElementById(id)
      if (el && el.getBoundingClientRect().top < window.innerHeight * 0.35) current = id
    })
    document.querySelectorAll('.toc-link').forEach(function (a) {
      a.classList.toggle('on', a.getAttribute('href') === '#' + current)
    })
  }
  window.addEventListener('scroll', spy, { passive: true })
  spy()
})

onBeforeUnmount(() => {
  if (spy) window.removeEventListener('scroll', spy)
  spy = null
})
</script>

